import { expect, Page } from '@playwright/test';

/**
 * Page Object — Checkout – Katalon Shop.
 * https://cms.demo.katalon.com/checkout/
 *
 * Generated by the Zennx Playwright studio from a recorded session.
 * Locators live here and nowhere else, so a renamed button is one edit.
 */
export class CheckoutPage {
    readonly page: Page;

    private readonly checkoutHeading = () => this.page.getByRole('heading', { name: 'Checkout' });
    private readonly placeOrderButton = () => this.page.getByRole('button', { name: 'Place order' });
    private readonly billingFirstNameIsARequiredFieldBillingLastNameIs = () => this.page.getByRole('alert');

    constructor(page: Page) {
        this.page = page;
    }

    async expectCheckoutHeadingVisible(): Promise<void> {
        await expect(this.checkoutHeading()).toBeVisible();
    }

    async clickPlaceOrderButton(): Promise<void> {
        await this.placeOrderButton().click();
    }

    async expectBillingFirstNameIsARequiredFieldBillingLastNameIsText(expected: string | RegExp): Promise<void> {
        await expect(this.billingFirstNameIsARequiredFieldBillingLastNameIs()).toContainText(expected);
    }
}
